function vpInit(v){const preset=(R().vehicleTypes||[]).find(x=>x.id===(v.vehicleTypeId||v.vehicle_type_id||v.presetId));v.name??=v.vehicle_name||v.type||preset?.name||'Vehicle';v.type??=v.vehicle_type||preset?.name||'Vehicle';v.vehicleTypeId??=v.vehicle_type_id||preset?.id;v.equipment??=[];v.damages??=[];v.userModifiers??={};v.specialRules??=v.special_rules||preset?.special_rules||[];for(const [key] of vpStatFields)v[key]??=preset?.[key]??0;for(const key of ['body_slots','drive_slots','engine_slots'])v[key]??=preset?.[key]??0;if(!v.hardpoints)v.hardpoints=(vpHardpointTemplates[v.vehicleTypeId]||[]).map(h=>({id:id(),operatedBy:h.operated_by||'',arcs:[...(h.arcs||[])],defaultArcs:[...(h.arcs||[])],location:h.location||'',weaponId:'',creditsIncrease:0}));return v}
