function vpStats(v,pending={}){return Object.fromEntries(vpStatFields.map(([key])=>[key,num(v[key])+num(vpModifiers(v,'Damage')[key])+num(vpModifiers(v,'Upgrades')[key])+num(vpModifiers(v,'User')[key])+num(pending[key])]))}
