function vpCrewOptions(g){return g.fighters.filter(f=>(f.subtypes||f.fighter_subtypes||[f.subtype||f.type]).includes('Crew')&&!(g.vehicles||[]).some(v=>(v.crew||v.fighter_id)===f.id)).map(f=>({value:f.id,label:f.name+' - '+f.type+' ('+num(f.xp)+' XP)'+(f.status!=='Active'?' · '+f.status:'')}))}
