 const drawRules=()=>`<div class="vp-special-rules">${draft.rules.map((rule,i)=>`<span class="chip">${vpRuleMarkup(rule)}${!vpLocomotions.includes(rule)&&rule!=='Locomotion'?vpButton('rule-remove','×',`data-index="${i}" aria-label="Remove ${esc(rule)}"`):''}</span>`).join('')}</div>`;
